server {
    listen 80;
    server_name example.internal;

    location /api/ {
        proxy_pass http://backend:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location /static/ {
        alias /var/www/static/;
        expires 30d;
    }
}

import { Client } from './vendor-sdk.js';

// The SDK reads its credential from the environment; it is never hardcoded here.
export function createClient() {
  return new Client({
    apiKey: process.env.SERVICE_API_KEY,
    baseUrl: process.env.SERVICE_BASE_URL ?? 'https://api.example.internal',
    timeoutMs: 10_000,
  });
}

import os

from vendor_sdk import Client


def create_client() -> Client:
    """Build the SDK client from environment configuration."""
    return Client(
        api_key=os.environ["SERVICE_API_KEY"],
        base_url=os.environ.get("SERVICE_BASE_URL", "https://api.example.internal"),
        timeout=10,
    )

resource "aws_instance" "web" {
  ami           = var.ami_id
  instance_type = "t3.micro"

  tags = {
    Name        = "web-server"
    Environment = var.environment
  }
}

variable "ami_id" {
  type        = string
  description = "AMI id for the web server"
}
